(function(){
"use strict";
var openBtn=document.getElementById('mkcChatOpen'),closeBtn=document.getElementById('mkcChatClose'),panel=document.getElementById('mkcChatPanel'),log=document.getElementById('mkcChatLog'),form=document.getElementById('mkcChatForm'),input=document.getElementById('mkcChatInput'),greeted=false;
var BOOK='You can use the <a href="contact.html">Book a consultation</a> page, or call <a href="tel:+19059973200">+1 905-997-3200</a> during listed hours (Mon–Fri, 8:00 a.m.–5:00 p.m.). Calling is the surest way to arrange a time.';
var FALLBACK='I can only help with the information on this page — services, hours, location, booking, what to bring, and fees in general. For anything about your personal case, please book a consultation or call <a href="tel:+19059973200">+1 905-997-3200</a>.';
function add(text,who){var d=document.createElement('div');d.className='mkc-msg '+who;if(who==='bot'){d.innerHTML=text;}else{d.textContent=text;}log.appendChild(d);log.scrollTop=log.scrollHeight;return d;}
function answer(raw){
 var q=' '+raw.toLowerCase().replace(/[^a-z0-9+ ]/g,' ')+' ';
 if(/(passport number|sin number|social insurance|uci|date of birth|dob|my passport|share.*document|upload)/.test(q))return 'Please don’t share passport numbers, personal details, or documents in this chat — this chat does not save or send messages, and it isn’t a secure way to share them. Bring anything relevant to your consultation itself, and MKC can advise you there. To arrange one, call <a href="tel:+19059973200">+1 905-997-3200</a>.';
 if(/(fee|fees|cost|price|charge|how much)/.test(q))return 'Fees are confirmed at consultation — I don’t have any prices to quote here, and I can’t estimate one for your case. At your consultation you can ask what would apply before deciding how to proceed. '+BOOK;
 if(/(express entry|pnp|provincial nominee|sponsor|sponsorship|spousal|super visa|lmia|refugee|appeal)/.test(q))return 'That specific pathway isn’t listed among the services described on this page, so I can’t confirm MKC offers it. The services listed here are tourist visas, student visas, work permits &amp; extensions, permanent residence, citizenship, and general immigration consulting. Please ask MKC directly during a consultation whether they can help with your situation. '+BOOK;
 if(/(tourist visa|visitor visa|tourist|visitor record|visit canada|visiting canada|travel visa|trv|family visit|extend my stay|extend (my|our) visit|stay longer)/.test(q))return 'MKC lists <strong>tourist (visitor) visas &amp; extensions</strong> among its services: help preparing a visitor visa application, or extending your stay, to visit Canada for travel or to see family. Whether it fits your situation is a question for a consultation. '+BOOK;
 if(/(study permit|student visa|study visa|student permit|study in canada|studying in canada|international student)/.test(q))return 'MKC lists <strong>study permits &amp; student visas</strong> among its services: help preparing a study permit application to study at a school in Canada. Whether it fits your situation is a question for a consultation. '+BOOK;
 if(/(work permit|work visa|extension|extend|job permit)/.test(q))return 'MKC lists <strong>work permits &amp; extensions</strong> among its services, including repeat applications as described by past clients. Whether that fits your situation is a personal question for a consultation. '+BOOK;
 if(/(permanent residence|permanent resident|\bpr\b|residency)/.test(q))return 'MKC lists <strong>permanent residence</strong> applications among its services, with careful preparation at each stage. I can’t assess eligibility or timelines here — that needs a consultation. '+BOOK;
 if(/(citizenship|citizen)/.test(q))return 'MKC lists <strong>Canadian citizenship</strong> among its services — clients have described it as the step after permanent residence. For eligibility and what applies to you, please book a consultation. '+BOOK;
 if(/(bring|documents needed|first consultation|prepare)/.test(q))return 'General information only: people often bring to the consultation itself things like a passport or other ID, any current status documents, and prior immigration correspondence — plus a list of their questions. Please bring those to your appointment, <strong>not</strong> to this chat. MKC will advise what else may be needed in your case.';
 if(/(hour|open|close|when)/.test(q))return 'Listed hours are <strong>Monday–Friday, 8:00 a.m.–5:00 p.m.</strong>, Saturday–Sunday closed. Please call <a href="tel:+19059973200">+1 905-997-3200</a> before visiting.';
 if(/(address|located|location|direction|where|map|mississauga|streetsville)/.test(q))return 'The address shown on this page is <strong>154 Queen St S, Unit 212, Mississauga, ON L5M 2P4</strong> (Streetsville). You’ll find a map and a directions link on the <a href="contact.html">contact page</a>. Please call ahead to confirm before visiting.';
 if(/(phone|call|contact|reach)/.test(q))return 'You can call MKC at <a href="tel:+19059973200">+1 905-997-3200</a>, Mon–Fri 8:00 a.m.–5:00 p.m. as listed. No business email is published on this page.';
 if(/(book|appointment|consultation|meet|schedule|get started|start)/.test(q))return BOOK;
 if(/(guarantee|timeline|how long|chance|eligible|eligibility|qualify|will i|refused|refusal)/.test(q))return 'I can’t assess eligibility, chances, or timelines, and no consultant can guarantee a government decision. That’s exactly what a consultation is for. '+BOOK;
 if(/(service|offer|help with|do you do)/.test(q))return 'The services listed on this page are: <strong>tourist visas, student visas, work permits &amp; extensions, permanent residence, Canadian citizenship, and general immigration consulting</strong>. If your situation is different, ask during a consultation whether MKC can help.';
 if(/(morris|who are you|who is|about mkc|about morris|about you|consultant|experience|since when)/.test(q))return 'This page describes Morris King Catalig as an immigration consultant at MKC Immigration Solutions Inc in Mississauga, in that role since October 2018 as listed publicly. You can also find him via the LinkedIn link in the footer. For advice on your own case, please book a consultation.';
 if(/(review|rating|rated|google)/.test(q))return 'This page quotes excerpts from Google reviews and describes a 5.0 rating from 10 reviews on Google. Reviewer names aren’t shown, so none are added here.';
 if(/(privacy|cookie|personal information|data policy)/.test(q))return 'You can read how MKC handles personal information in the <a href="privacy.html">privacy policy</a>, and what this website stores in your browser in the <a href="cookies.html">cookies policy</a>.';
 if(/(hello|hi|hey|good morning|good afternoon)/.test(q))return 'Hello! I can answer general questions from this page — services, hours, location, booking, what to bring, or fees in general. Try one of the quick questions below, and please don’t share personal details here.';
 return FALLBACK;
}
function openChat(){panel.hidden=false;openBtn.setAttribute('aria-expanded','true');if(!greeted){greeted=true;add('Hello — I’m the MKC assistant. I answer only from the information on this page. <strong>General information only, not immigration or legal advice.</strong> How can I help?','bot');}setTimeout(function(){input.focus();},0);}
function closeChat(){panel.hidden=true;openBtn.setAttribute('aria-expanded','false');openBtn.focus();}
openBtn.addEventListener('click',function(){panel.hidden?openChat():closeChat();});
closeBtn.addEventListener('click',closeChat);
panel.addEventListener('keydown',function(e){if(e.key==='Escape'){e.preventDefault();closeChat();}});
document.querySelectorAll('.mkc-chat-chips button').forEach(function(b){b.addEventListener('click',function(){add(b.getAttribute('data-q'),'user');add(answer(b.getAttribute('data-q')),'bot');input.focus();});});
form.addEventListener('submit',function(e){e.preventDefault();var v=input.value.trim();if(!v)return;add(v,'user');input.value='';add(answer(v),'bot');input.focus();});
})();
